for cls,id in [('NobuBeamCreatePacket','nobu_beam_create'),('NobuSetTargetPacket','nobu_set_target'),('ReplicaSwitchPacket','replica_switch')]:
 s=(orig/('networking/'+cls+'.java')).read_text(encoding='utf-8').replace('import net.neoforged.neoforge.network.handling.IPayloadContext;','');s=s.replace('IPayloadContext context','net.minecraft.server.level.ServerPlayer player').replace('      Player player = context.player();\n','').replace('context.player()','player');s=s.replace('public class '+cls+' implements CustomPacketPayload {','public class '+cls+' implements CustomPacketPayload {\n public static final Type<'+cls+'> TYPE=new Type<>(net.minecraft.resources.Identifier.fromNamespaceAndPath("mahoutsukai","'+id+'"));');s=re.sub(r'return MahouPackets\.\w+;', 'return TYPE;',s)
 if cls=='NobuBeamCreatePacket':
  s=s.replace('      Level world = player.level();','''      if(player.isSpectator() || player.hasEffect(stepsword.mahoutsukai.potion.ModEffects.BOUND) || !(player.getMainHandItem().getItem() instanceof Nobu) || message.fire<0 || message.fire>=NobuFirePacket.values().length || message.eids.size()>8)return;
      if(message.fire==NobuFirePacket.CREATE_BEAM.ordinal() && (!player.isUsingItem() || Utils.getMode(player.getUseItem())!=0))return;
      if(message.fire==NobuFirePacket.FIRE_BEAM.ordinal() && (!player.isUsingItem() || Utils.getMode(player.getUseItem())!=0))return;
      Level world = player.level();''').replace('if (e != null) {','if (e instanceof net.minecraft.world.entity.LivingEntity && e.isAlive() && e!=player && player.distanceToSqr(e)<=2500 && player.hasLineOfSight(e) && !stepsword.mahoutsukai.tile.exchange.ContractMahoujinTileEntity.isImmuneToSpell(player,e)) {',1)
 if cls=='NobuSetTargetPacket':
  s=s.replace('      Nobu.NobuUserStorage storage = Nobu.getStorage(player);','      if(player.isSpectator() || player.hasEffect(stepsword.mahoutsukai.potion.ModEffects.BOUND) || !(player.getMainHandItem().getItem() instanceof Nobu))return;\n      Nobu.NobuUserStorage storage = Nobu.getStorage(player);\n      if(storage==null)return;').replace('if (e != null) {','if (e instanceof net.minecraft.world.entity.LivingEntity && e.isAlive() && e!=player && player.distanceToSqr(e)<=2500 && player.hasLineOfSight(e)) {').replace('.ifRight(b -> storage.target = Either.right(b));','.ifRight(b -> {if(player.position().distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(b))<=2500 && player.level().hasChunkAt(b))storage.target = Either.right(b);});')
 if cls=='ReplicaSwitchPacket':s=s.replace('      ItemStack stack = player.getMainHandItem();','      if(message.slot<0 || message.slot>6 || player.isSpectator() || player.hasEffect(stepsword.mahoutsukai.potion.ModEffects.BOUND))return;\n      ItemStack stack = player.getMainHandItem();')
 write(main/('networking/'+cls+'.java'),s)
